\draw[{Stealth}-{Stealth}] (0,-3)--(0,3) node[above] {$y$};
\draw[blue, thick] (Q)--(P);
\pic[draw, "$\theta$", angle radius=0.85cm, angle eccentricity=1.6] {angle=X--O--P};
\node at (2.05,1.9) {$m<0$};
\end{tikzpicture}
[/tikz]

